<script lang="ts">
 import {onMount} from 'svelte';
 import {page} from '$app/state';
 import {goto} from '$app/navigation';
 import ContextShell from '$lib/components/harness/ContextShell.svelte';
 import ContextWeave from '$lib/components/harness/ContextWeave.svelte';
 import HarnessCard from '$lib/components/harness/HarnessCard.svelte';
 import Icon from '$lib/components/harness/Icon.svelte';
 import {createCollection} from '$lib/harness/social.svelte';
 import type {PageData} from './$types';
 let {data}:{data:PageData}=$props();
 let search=$state(''),kind=$state('AGENTS.md'),sort=$state('curated');
 const collection=createCollection();
 onMount(()=>{collection.load();});
 let view=$derived(page.url.searchParams.get('view')??'discover');
 let topic=$derived(page.url.searchParams.get('topic')??'all');
 let filtered=$derived.by(()=>{
  const source=view==='saved'?collection.savedHarnesses:view==='following'?collection.followingHarnesses:data.harnesses;
  let rows=source.filter(h=>(kind==='All context'||(h.snapshot.path.split('/').at(-1)??'').toUpperCase()===kind.toUpperCase())&&(topic==='all'||h.topic===topic)&&`${h.title} ${h.description} ${h.snapshot.owner} ${h.snapshot.content}`.toLowerCase().includes(search.toLowerCase()));
  if(view==='saved')rows=rows.filter(h=>collection.saved.includes(h.id));
  if(view==='following')rows=rows.filter(h=>collection.following.includes(h.snapshot.owner.toLowerCase()));
  return sort==='updated'?[...rows].sort((a,b)=>Date.parse(b.snapshot.updatedAt)-Date.parse(a.snapshot.updatedAt)):rows;
 });
 let people=$derived([...new Set(data.harnesses.map(h=>h.snapshot.owner))].slice(0,4));
</script>
<svelte:head><title>Loooom — Share your AGENTS.md</title><meta name="description" content="Let anyone try on your harness"/></svelte:head>
<ContextShell>
 <section class="home-hero">
  <div class="hero-copy"><h1>Share your<br/><span>AGENTS.md.</span></h1><p>Let anyone try on your harness</p><div class="hero-actions"><a href="#discover" class="button primary">Explore AGENTS.md <Icon name="arrow" size={17}/></a></div><div class="source-promise"><Icon name="git" size={13}/><span>Source and commit included.</span></div></div>
  <ContextWeave/>
 </section>
 <div class="context-types" role="group" aria-label="Context file types">
  <button class="primary-context" class:chosen={kind==='AGENTS.md'} onclick={()=>kind='AGENTS.md'} aria-pressed={kind==='AGENTS.md'}><span class="type-symbol"><Icon name="code" size={21}/></span><span><strong>AGENTS.md</strong><span>Working rules for your agent</span></span><Icon name="arrow" size={16}/></button>
  <div class="more-context"><span>More context</span>{#each ['ME.md','SOUL.md','DESIGN.md'] as type}<button class:chosen={kind===type} aria-pressed={kind===type} onclick={()=>kind=type}>{type}</button>{/each}</div>
 </div>
 <section class="discovery" id="discover" aria-labelledby="discover-title">
  <div class="section-heading"><div><h2 id="discover-title">{view==='saved'?'Your collection':view==='following'?'Following':'Browse harnesses'}</h2><p>{view==='discover'?'Read the files. Try what fits.':view==='saved'?'Your saved files.':'Files from people you follow.'}</p></div></div>
  <div class="feed-layout"><div class="feed-main">
   <div class="feed-tabs"><div role="group" aria-label="Context file type">{#each ['All context','AGENTS.md','ME.md','SOUL.md','DESIGN.md'] as type}<button class:selected={kind===type} aria-pressed={kind===type} onclick={()=>kind=type}>{type}</button>{/each}</div><label class="sort-label"><span class="sr-only">Sort files</span><select bind:value={sort}><option value="curated">Featured</option><option value="updated">Last updated</option></select></label></div>
   <div class="feed-search"><Icon name="search" size={17}/><input aria-label="Search context" placeholder="Search people or files…" bind:value={search}/>{#if search}<button onclick={()=>search=''} aria-label="Clear search">Clear</button>{/if}</div>
   {#if topic!=='all'}<div class="topic-filter">Topic: {topic}<a href="/#discover">Clear filter</a></div>{/if}
   {#if collection.message}<div class="notice" role="status">{collection.message} {#if collection.message.startsWith('Sign in')}<a href="/login?next=/">Sign in <Icon name="arrow" size={13}/></a>{/if}</div>{/if}
   <div class="feed-caption"><span>{filtered.length} {filtered.length===1?'file':'files'} to explore</span><span>Source linked <Icon name="git" size={12}/></span></div>
   {#if filtered.length}<div class="harness-grid">{#each filtered as harness (harness.id)}<HarnessCard {harness} saved={collection.saved.includes(harness.id)} busy={!!collection.busy} onsave={(id)=>collection.toggle('save',id)}/>{/each}</div>{:else}<div class="empty-state"><Icon name={view==='saved'?'bookmark':'file'} size={28}/><h3>{search?'No matching files.':view==='following'?'Follow a creator.':view==='saved'?'No saved files.':`No ${kind} files yet.`}</h3><p>{search?'Try another search.':view==='following'?'Follow someone to see their files.':view==='saved'?'Save a file here. Sign in to sync it.':'Try another file type.'}</p><button class="button secondary" onclick={()=>{search='';kind='All context';goto('/#discover');}}>Show all context<Icon name="arrow" size={16}/></button></div>{/if}
   <p class="curation-note">Curated from public GitHub files. Authors may not use or endorse Loooom.</p>
  </div>
  <aside class="discovery-aside">
   <a class="eval-feature" href="/evals"><div class="eval-top"><Icon name="flask" size={21}/></div><h3>Test your<br/>harness.</h3><p>Same task. With and without your files.</p><div class="eval-comparison" aria-hidden="true"><span>without</span><i></i><span>with you</span></div><span class="eval-link">Try personal evals <Icon name="arrow" size={17}/></span><span class="eval-footnote">Open source · runs locally</span></a>
   <section class="people-list" aria-labelledby="people-title"><h3 id="people-title">People to follow</h3>{#each people as owner,i}<div class="person-row"><a href={`/people/${owner}`}><span class="person-avatar" class:lavender={i===1}>{owner.slice(0,2)}</span><span><strong>@{owner}</strong><small>{data.harnesses.filter(h=>h.snapshot.owner===owner).length} shared context</small></span></a><button disabled={!!collection.busy} class:is-following={collection.following.includes(owner.toLowerCase())} onclick={()=>collection.toggle('follow',owner.toLowerCase())} aria-label={`${collection.following.includes(owner.toLowerCase())?'Unfollow':'Follow'} ${owner}`}><Icon name={collection.following.includes(owner.toLowerCase())?'check':'plus'} size={16}/></button></div>{/each}</section>
   <div class="open-note"><Icon name="git" size={19}/><h3>Keep your source.</h3><p>Edit on GitHub. Shared snapshots keep their source and commit.</p></div>
  </aside></div>
 </section>
</ContextShell>
